function Logo({ collapsed = false }: { collapsed?: boolean }) {
  return <div className="flex items-center gap-3 px-1"><div className="relative grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Brain className="size-5" /><span className="absolute -right-1 -top-1 size-2 rounded-full bg-indigo-300 ring-2 ring-sidebar" /></div>{!collapsed && <div><div className="font-semibold tracking-tight">Cortex<span className="text-primary">Search</span></div><div className="text-[10px] font-medium uppercase tracking-[.18em] text-muted-foreground">Trusted knowledge</div></div>}</div>
}
function IconButton({ icon: Icon, label, onClick, className = '' }: any) { return <button aria-label={label} title={label} onClick={onClick} className={`grid size-9 place-items-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${className}`}><Icon className="size-4" /></button> }
function StatusBadge({ children, tone = 'green' }: { children: React.ReactNode, tone?: string }) { return <span className={`inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-xs font-medium ${tone === 'green' ? 'bg-emerald-500/10 text-emerald-600' : tone === 'amber' ? 'bg-amber-500/10 text-amber-600' : tone === 'red' ? 'bg-red-500/10 text-red-600' : 'bg-muted text-muted-foreground'}`}><span className="size-1.5 rounded-full bg-current" />{children}</span> }
function MetricCard({ icon: Icon, label, value, trend, color = 'indigo' }: any) { return <div className="rounded-xl border bg-card p-4 shadow-sm"><div className="flex items-start justify-between"><div className={`grid size-9 place-items-center rounded-lg ${color === 'green' ? 'bg-emerald-500/10 text-emerald-600' : color === 'amber' ? 'bg-amber-500/10 text-amber-600' : 'bg-primary/10 text-primary'}`}><Icon className="size-4" /></div><span className="text-xs font-medium text-emerald-600">{trend}</span></div><div className="mt-4 text-2xl font-semibold tracking-tight">{value}</div><div className="mt-1 text-xs text-muted-foreground">{label}</div></div> }
function Confidence({ value }: { value: number }) { return <div className="flex items-center gap-2"><div className="h-1.5 w-16 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${value >= 90 ? 'bg-emerald-500' : value >= 70 ? 'bg-amber-500' : 'bg-red-500'}`} style={{width: `${value}%`}} /></div><span className="text-xs font-medium">{value}%</span></div> }
function SourceCard({ source, onOpen }: { source: any[], onOpen: () => void }) { return <button onClick={onOpen} className="group flex w-full items-center gap-3 rounded-lg border bg-card p-3 text-left transition-all hover:border-primary/40 hover:shadow-sm"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-red-500/10 text-red-600"><FileText className="size-4" /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium">{source[0]}</div><div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground"><span>{source[1]}</span><span>•</span><span>{source[2]}</span></div></div><div className="hidden text-right sm:block"><div className="text-xs font-semibold text-emerald-600">{source[3]}%</div><div className="text-[10px] text-muted-foreground">relevance</div></div><ArrowUpRight className="size-4 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" /></button> }

export default function CortexApp() {
  const [path, setPath] = useState('/dashboard')
  const [collapsed, setCollapsed] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [dark, setDark] = useState(false)
  const [query, setQuery] = useState('')
  const [chatQuery, setChatQuery] = useState('')
  const [chatStarted, setChatStarted] = useState(false)
  const [processing, setProcessing] = useState(false)
  const [toast, setToast] = useState('')
  const [showCommand, setShowCommand] = useState(false)
  const [sourceOpen, setSourceOpen] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState(0)

  useEffect(() => { document.documentElement.classList.toggle('dark', dark) }, [dark])
  useEffect(() => { const handler = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setShowCommand(true) } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler) }, [])
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(''), 2600); return () => clearTimeout(t) } }, [toast])
  const go = (next: string) => { setPath(next); setMobileOpen(false); window.history.pushState({}, '', next) }
  const ask = (value: string) => { setChatQuery(value); setPath('/chat'); setChatStarted(false); setMobileOpen(false); window.history.pushState({}, '', '/chat') }
  const send = () => { if (!chatQuery.trim()) return; setChatStarted(true); setProcessing(true); setTimeout(() => setProcessing(false), 2200) }
  const title = useMemo(() => ({'/dashboard':'Ask Cortex','/chat':'Remote Work Policy','/conversations':'Conversations','/documents':'Documents','/collections':'Collections','/search':'Global Search','/analytics':'Analytics','/admin/users':'Users & Roles','/settings':'Settings'} as any)[path] || 'Ask Cortex', [path])

  return <div className={dark ? 'dark' : ''}><div className="flex min-h-screen bg-background text-foreground">
    <aside className={`fixed inset-y-0 left-0 z-40 flex flex-col border-r bg-sidebar p-4 transition-all duration-200 lg:relative ${collapsed ? 'w-[76px]' : 'w-[256px]'} ${mobileOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
      <div className="flex items-center justify-between"><Logo collapsed={collapsed} /><IconButton icon={collapsed ? PanelLeftOpen : PanelLeftClose} label="Collapse sidebar" onClick={() => setCollapsed(!collapsed)} className="hidden lg:grid" /></div>
      <button onClick={() => ask('')} className={`mt-7 flex items-center gap-3 rounded-lg bg-primary px-3 py-2.5 text-sm font-medium text-primary-foreground shadow-sm transition hover:bg-primary/90 ${collapsed ? 'justify-center' : ''}`}><Plus className="size-4" />{!collapsed && 'New question'}{!collapsed && <kbd className="ml-auto rounded border border-primary-foreground/20 px-1.5 py-0.5 text-[10px] font-normal">⌘ K</kbd>}</button>
      <div className="mt-6 flex flex-col gap-1">{navPrimary.map(item => <button key={item.path} onClick={() => go(item.path)} title={collapsed ? item.label : undefined} className={`flex items-center gap-3 rounded-lg px-3 py-2 text-sm transition ${path === item.path || (path.startsWith(item.path + '/') && item.path !== '/dashboard') ? 'bg-primary/10 font-medium text-primary' : 'text-muted-foreground hover:bg-accent hover:text-foreground'} ${collapsed ? 'justify-center' : ''}`}><item.icon className="size-4 shrink-0" />{!collapsed && item.label}</button>)}</div>
      {!collapsed && <div className="mt-7 px-3 text-[10px] font-semibold uppercase tracking-[.16em] text-muted-foreground">Administration</div>}
      <div className="mt-2 flex flex-col gap-1">{navAdmin.map(item => <button key={item.path} onClick={() => go(item.path)} title={collapsed ? item.label : undefined} className={`flex items-center gap-3 rounded-lg px-3 py-2 text-sm transition ${path === item.path ? 'bg-primary/10 font-medium text-primary' : 'text-muted-foreground hover:bg-accent hover:text-foreground'} ${collapsed ? 'justify-center' : ''}`}><item.icon className="size-4 shrink-0" />{!collapsed && item.label}</button>)}</div>
      {!collapsed && <div className="mt-8 flex min-h-0 flex-1 flex-col"><div className="flex items-center justify-between px-3 text-[10px] font-semibold uppercase tracking-[.16em] text-muted-foreground"><span>Recent</span><History className="size-3.5" /></div><div className="mt-3 flex flex-col gap-1">{recent.map((r, i) => <button key={r} onClick={() => ask(r)} className="truncate rounded-lg px-3 py-2 text-left text-xs text-muted-foreground hover:bg-accent hover:text-foreground">{r}</button>)}</div></div>}
      <div className={`mt-auto flex items-center gap-3 rounded-xl border bg-card p-2.5 ${collapsed ? 'justify-center' : ''}`}><div className="grid size-8 shrink-0 place-items-center rounded-full bg-indigo-100 text-xs font-semibold text-indigo-700">AM</div>{!collapsed && <><div className="min-w-0 flex-1"><div className="truncate text-xs font-medium">Alex Morgan</div><div className="truncate text-[10px] text-muted-foreground">Administrator</div></div><ChevronDown className="size-4 text-muted-foreground" /></>}</div>
    </aside>
    {mobileOpen && <button className="fixed inset-0 z-30 bg-black/20 lg:hidden" onClick={() => setMobileOpen(false)} aria-label="Close navigation" />}
    <div className="flex min-w-0 flex-1 flex-col"><header className="flex h-16 items-center justify-between border-b bg-background/95 px-4 backdrop-blur sm:px-6"><div className="flex items-center gap-3"><IconButton icon={Menu} label="Open navigation" onClick={() => setMobileOpen(true)} className="lg:hidden" /><div className="hidden items-center gap-2 text-sm text-muted-foreground sm:flex"><span className="font-medium text-foreground">{title}</span>{path !== '/dashboard' && <><ChevronRight className="size-3.5" /><span>CortexSearch</span></>}</div></div><div className="flex items-center gap-1"><button onClick={() => setShowCommand(true)} className="mr-2 hidden items-center gap-2 rounded-lg border px-2.5 py-1.5 text-xs text-muted-foreground transition hover:bg-accent md:flex"><Search className="size-3.5" />Quick search <kbd className="rounded bg-muted px-1.5 py-0.5 text-[10px]">⌘ K</kbd></button><IconButton icon={dark ? Sun : Moon} label="Toggle theme" onClick={() => setDark(!dark)} /><IconButton icon={Bell} label="Notifications" onClick={() => setToast('No new notifications')} /><div className="ml-2 grid size-8 place-items-center rounded-full bg-indigo-100 text-xs font-semibold text-indigo-700">AM</div></div></header><main className="min-w-0 flex-1 overflow-auto"><div className="mx-auto max-w-[1400px] p-4 sm:p-6 lg:p-8">{path === '/dashboard' && <Dashboard ask={ask} query={query} setQuery={setQuery} />}{path === '/chat' && <Chat chatQuery={chatQuery} setChatQuery={setChatQuery} started={chatStarted} processing={processing} send={send} onSource={() => setSourceOpen(true)} onToast={setToast} />}{path === '/conversations' && <Conversations go={go} onToast={setToast} />}{path === '/documents' && <Documents uploading={uploading} progress={progress} onUpload={() => {setUploading(true); setProgress(0); const id=setInterval(()=>setProgress(v=>{if(v>=100){clearInterval(id); setUploading(false); setToast('Document uploaded successfully'); return 100} return v+20}), 300)}} go={go} />}{path.startsWith('/documents/') && <DocumentDetail onBack={() => go('/documents')} />}{path === '/collections' && <Collections go={go} />}{path.startsWith('/collections/') && <CollectionDetail onBack={() => go('/collections')} />}{path === '/search' && <SearchPage onSource={() => setSourceOpen(true)} />}{path === '/analytics' && <AnalyticsPage />}{path === '/admin/users' && <UsersPage onToast={setToast} />}{path === '/settings' && <SettingsPage onToast={setToast} />}</div></main></div>
    {toast && <div className="fixed bottom-5 right-5 z-50 flex items-center gap-3 rounded-lg border bg-card px-4 py-3 text-sm shadow-lg"><div className="grid size-6 place-items-center rounded-full bg-emerald-500/10 text-emerald-600"><Check className="size-3.5" /></div>{toast}<button onClick={() => setToast('')}><X className="size-3.5 text-muted-foreground" /></button></div>}
    {showCommand && <CommandPalette close={() => setShowCommand(false)} go={(p: string) => {setShowCommand(false); go(p)}} />}
    {sourceOpen && <SourceModal close={() => setSourceOpen(false)} />}
  </div></div>
}

function PageIntro({ eyebrow, title, description, action }: any) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 text-xs font-semibold uppercase tracking-[.16em] text-primary">{eyebrow}</div><h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">{title}</h1>{description && <p className="mt-2 text-sm text-muted-foreground">{description}</p>}</div>{action}</div> }
function Dashboard({ ask, query, setQuery }: any) { return <div><div className="mx-auto max-w-4xl py-8 text-center sm:py-12"><div className="mx-auto mb-5 grid size-12 place-items-center rounded-2xl bg-primary/10 text-primary"><Sparkles className="size-6" /></div><h1 className="text-3xl font-semibold tracking-tight sm:text-4xl">Good evening, Alex</h1><p className="mt-3 text-sm text-muted-foreground sm:text-base">Search your organization&apos;s knowledge and get trusted answers.</p><div className="mt-8 rounded-2xl border bg-card p-2 text-left shadow-sm ring-1 ring-black/[.02] focus-within:border-primary/40 focus-within:ring-4 focus-within:ring-primary/10"><div className="flex items-start gap-3 px-3 py-3"><Search className="mt-1 size-5 shrink-0 text-muted-foreground" /><textarea value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();ask(query)}}} rows={2} placeholder="Ask anything about your organization&apos;s knowledge..." className="min-h-[56px] flex-1 resize-none bg-transparent text-sm outline-none placeholder:text-muted-foreground" /></div><div className="flex items-center justify-between border-t px-2 pt-2"><div className="flex items-center gap-1"><IconButton icon={Paperclip} label="Attach file" /><button className="hidden items-center gap-2 rounded-md px-2 py-1.5 text-xs text-muted-foreground hover:bg-accent sm:flex"><Database className="size-3.5" /> All collections <ChevronDown className="size-3" /></button></div><div className="flex items-center gap-2"><kbd className="hidden rounded border bg-muted px-1.5 py-1 text-[10px] text-muted-foreground sm:block">Shift + Enter</kbd><button onClick={()=>ask(query)} className="grid size-9 place-items-center rounded-lg bg-primary text-primary-foreground transition hover:bg-primary/90" aria-label="Ask Cortex"><Send className="size-4" /></button></div></div></div></div><section><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-semibold">Suggested questions</h2><span className="text-xs text-muted-foreground">Try a quick start</span></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{questions.map((q,i)=><button key={q} onClick={()=>ask(q)} className="group rounded-xl border bg-card p-4 text-left transition hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-sm"><div className="mb-5 grid size-8 place-items-center rounded-lg bg-muted text-primary">{i===0 ? <FileSearch className="size-4" /> : i===1 ? <ShieldCheck className="size-4" /> : i===2 ? <FileBarChart className="size-4" /> : <History className="size-4" />}</div><div className="text-sm font-medium leading-5">{q}</div><ArrowUpRight className="mt-3 size-4 text-muted-foreground transition group-hover:translate-x-0.5 group-hover:text-primary" /></button>)}</div></section><section className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard icon={FileText} label="Documents" value="12,482" trend="+8.2%" /><MetricCard icon={Library} label="Collections" value="18" trend="+2 this month" color="green" /><MetricCard icon={MessageCircle} label="Questions answered" value="48,291" trend="+14.6%" /><MetricCard icon={Gauge} label="Average confidence" value="92%" trend="+1.8%" color="green" /></section><div className="mt-8 grid gap-6 xl:grid-cols-[1.4fr_1fr]"><section className="rounded-xl border bg-card"><div className="flex items-center justify-between border-b p-5"><div><h2 className="font-semibold">Recent conversations</h2><p className="mt-1 text-xs text-muted-foreground">Your team&apos;s latest knowledge searches</p></div><button className="text-xs font-medium text-primary hover:underline">View all</button></div><div className="divide-y">{[['Remote Work Policy','Can employees work remotely from another country?','6 sources','94%','12 min ago'],['Security Incident Process','What should I do after discovering an incident?','4 sources','97%','Yesterday'],['Employee Expense Policy','What expenses require pre-approval?','8 sources','91%','Yesterday'],['Engineering Onboarding','Where can I find the service ownership guide?','3 sources','96%','2 days ago']].map(r=><div key={r[0]} className="flex items-center gap-3 p-4"><div className="grid size-8 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><MessageCircle className="size-4" /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium">{r[0]}</div><div className="mt-1 truncate text-xs text-muted-foreground">{r[1]}</div></div><div className="hidden text-right sm:block"><div className="text-xs font-medium">{r[3]}</div><div className="text-[10px] text-muted-foreground">{r[2]} · {r[4]}</div></div><MoreHorizontal className="size-4 text-muted-foreground" /></div>)}</div></section><section className="rounded-xl border bg-card p-5"><div className="flex items-start justify-between"><div><h2 className="font-semibold">Knowledge overview</h2><p className="mt-1 text-xs text-muted-foreground">Index health across your workspace</p></div><div className="grid size-9 place-items-center rounded-lg bg-emerald-500/10 text-emerald-600"><Activity className="size-4" /></div></div><div className="mt-6 flex flex-col gap-4">{[['Documents indexed','12,482','99.8%'],['Documents processing','24','In progress'],['Total chunks','1.8M','+12.4k this week'],['Last indexing time','Today, 9:42 AM','Healthy']].map(r=><div key={r[0]} className="flex items-center justify-between"><div><div className="text-xs text-muted-foreground">{r[0]}</div><div className="mt-1 font-semibold">{r[1]}</div></div><span className="text-xs text-muted-foreground">{r[2]}</span></div>)}</div><button className="mt-6 flex items-center gap-2 text-xs font-medium text-primary hover:underline"><FileText className="size-3.5" />View documents <ArrowUpRight className="size-3.5" /></button></section></div></div> }

function Chat({ chatQuery, setChatQuery, started, processing, send, onSource, onToast }: any) { return <div className="mx-auto flex max-w-4xl flex-col"><div className="mb-6 flex items-center justify-between"><div><div className="flex items-center gap-2"><h1 className="text-xl font-semibold">Remote Work Policy</h1><span className="rounded-full bg-primary/10 px-2 py-1 text-[10px] font-medium text-primary">HR Policies</span></div><p className="mt-1 text-xs text-muted-foreground">Grounded conversation · 6 sources</p></div><div className="flex items-center gap-1"><button className="hidden items-center gap-2 rounded-lg border px-3 py-2 text-xs font-medium sm:flex"><Database className="size-3.5 text-primary" /> HR Policies <ChevronDown className="size-3.5" /></button><IconButton icon={Share2} label="Share conversation" onClick={()=>onToast('Conversation shared')} /><IconButton icon={MoreHorizontal} label="More options" /></div></div>{!started && !chatQuery && <div className="rounded-2xl border border-dashed bg-card p-10 text-center"><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-primary/10 text-primary"><Bot className="size-6" /></div><h2 className="mt-4 font-semibold">Ask Cortex about your knowledge</h2><p className="mx-auto mt-2 max-w-md text-sm text-muted-foreground">Answers are grounded in your organization&apos;s documents with citations and confidence scores.</p></div>}{chatQuery && <div className="flex justify-end"><div className="max-w-[85%] rounded-2xl rounded-br-md bg-primary px-4 py-3 text-sm leading-6 text-primary-foreground">{chatQuery}</div></div>}{processing && <RAGProgress />}{started && !processing && <div className="mt-6 flex gap-3"><div className="grid size-8 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground"><Brain className="size-4" /></div><div className="min-w-0 flex-1"><div className="prose prose-sm max-w-none dark:prose-invert"><p>Employees may work remotely outside their home country for up to <strong>30 consecutive days</strong>, subject to manager approval and applicable local legal requirements <button onClick={onSource} className="rounded bg-primary/10 px-1 text-xs font-semibold text-primary hover:bg-primary/20">[1]</button>.</p><p>Before working internationally, employees should:</p><ul><li>Receive written approval from their manager and People Operations.</li><li>Confirm that the destination is supported under our global mobility framework.</li><li>Complete any required tax, payroll, or data protection review.</li></ul></div><div className="mt-5 rounded-xl border bg-muted/30 p-4"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2 text-sm font-semibold"><FileSearch className="size-4 text-primary" /> Sources <span className="rounded-full bg-primary/10 px-1.5 py-0.5 text-[10px] text-primary">6</span></div><button onClick={onSource} className="text-xs font-medium text-primary hover:underline">View all</button></div><div className="flex flex-col gap-2">{sources.map(s=><SourceCard key={s[0]} source={s} onOpen={onSource} />)}</div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t pt-4"><div className="flex items-center gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-1.5 font-medium text-emerald-600"><span className="size-2 rounded-full bg-emerald-500" />Confidence 94%</span><span>2.4s response</span><span>6 sources</span></div><div className="flex items-center gap-1"><IconButton icon={Copy} label="Copy response" onClick={()=>onToast('Answer copied')} /><IconButton icon={ThumbsUp} label="Helpful" onClick={()=>onToast('Feedback submitted')} /><IconButton icon={ThumbsDown} label="Not helpful" onClick={()=>onToast('Feedback submitted')} /><IconButton icon={RefreshCw} label="Regenerate" onClick={()=>onToast('Regenerating answer')} /></div></div></div></div>}
      <div className="sticky bottom-0 mt-8 bg-background pb-2 pt-2"><div className="rounded-2xl border bg-card p-2 shadow-sm focus-within:border-primary/40 focus-within:ring-4 focus-within:ring-primary/10"><div className="flex items-center gap-2"><IconButton icon={Paperclip} label="Attach file" /><input value={chatQuery} onChange={e=>setChatQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.nativeEvent.isComposing){e.preventDefault();send()}}} placeholder="Ask a follow-up question..." className="flex-1 bg-transparent px-1 text-sm outline-none placeholder:text-muted-foreground" /><IconButton icon={Mic} label="Voice input" /><button onClick={send} className="grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground" aria-label="Send question"><Send className="size-4" /></button></div></div><p className="mt-2 text-center text-[10px] text-muted-foreground">CortexSearch can make mistakes. Verify important information in the cited sources.</p></div></div> }
function RAGProgress() { const steps=['Searching your knowledge base...','Retrieving relevant documents...','Ranking sources...','Generating grounded answer...']; return <div className="my-6 flex gap-3"><div className="grid size-8 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary"><Sparkles className="size-4 animate-pulse" /></div><div className="rounded-xl border bg-card px-4 py-3"><div className="flex items-center gap-2 text-sm font-medium"><span className="size-2 animate-pulse rounded-full bg-primary" /> Grounding answer in your knowledge base</div><div className="mt-3 flex flex-col gap-2">{steps.map((s,i)=><div key={s} className="flex items-center gap-2 text-xs text-muted-foreground"><Check className={`size-3.5 ${i<2?'text-emerald-500':'text-muted-foreground'}`} />{s}</div>)}</div></div></div> }

function Conversations({ go, onToast }: any) { const rows=[['Remote Work Policy','Can employees work abroad?','6 sources','94%','Today'],['Security Incident Process','What should employees do after discovering a security incident?','4 sources','97%','Yesterday'],['Employee Expense Policy','Which expenses need pre-approval?','8 sources','91%','Yesterday'],['Data Retention Rules','How long do we retain customer records?','5 sources','95%','Mon, Jun 16'],['Engineering Onboarding','Where is the service ownership guide?','3 sources','96%','Jun 14']]; return <div><PageIntro eyebrow="Knowledge history" title="Conversations" description="Review and manage your previous knowledge searches." action={<button onClick={()=>go('/chat')} className="flex items-center justify-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground"><Plus className="size-4" />New conversation</button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-1 rounded-lg bg-muted p-1"><button className="rounded-md bg-card px-3 py-1.5 text-xs font-medium shadow-sm">All</button><button className="rounded-md px-3 py-1.5 text-xs text-muted-foreground">My conversations</button><button className="rounded-md px-3 py-1.5 text-xs text-muted-foreground">Shared</button></div><div className="flex items-center gap-2 rounded-lg border bg-card px-3 py-2 text-xs text-muted-foreground sm:w-64"><Search className="size-3.5" /><input className="w-full bg-transparent outline-none" placeholder="Search conversations" /></div></div><div className="overflow-hidden rounded-xl border bg-card"><div className="hidden grid-cols-[1.4fr_2fr_.8fr_.8fr_1fr_40px] gap-4 border-b bg-muted/30 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground md:grid"><span>Conversation</span><span>Last question</span><span>Sources</span><span>Confidence</span><span>Updated</span><span /></div>{rows.map(r=><div key={r[0]} className="grid gap-2 border-b px-5 py-4 last:border-0 md:grid-cols-[1.4fr_2fr_.8fr_.8fr_1fr_40px] md:items-center md:gap-4"><div className="flex items-center gap-3"><div className="grid size-8 place-items-center rounded-lg bg-primary/10 text-primary"><MessageCircle className="size-4" /></div><span className="text-sm font-medium">{r[0]}</span></div><div className="text-xs text-muted-foreground">{r[1]}</div><div className="text-xs text-muted-foreground">{r[2]}</div><div><Confidence value={Number.parseInt(r[3])} /></div><div className="text-xs text-muted-foreground">{r[4]}</div><button onClick={()=>onToast('Conversation actions opened')} aria-label="Conversation actions"><MoreHorizontal className="size-4 text-muted-foreground" /></button></div>)}</div></div> }

function Documents({ go, uploading, progress, onUpload }: any) { return <div><PageIntro eyebrow="Knowledge library" title="Documents" description="Manage the knowledge available to CortexSearch." action={<div className="flex gap-2"><button onClick={onUpload} className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground"><Upload className="size-4" />Upload documents</button><button className="hidden items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium sm:flex"><Plus className="size-4" />Create collection</button></div>} />{uploading && <div className="mb-5 rounded-xl border bg-card p-4"><div className="flex items-center justify-between text-sm"><span className="flex items-center gap-2 font-medium"><Upload className="size-4 text-primary" />Uploading documents...</span><span className="text-xs text-muted-foreground">{progress}%</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{width:`${progress}%`}} /></div></div>}<div className="mb-5 flex flex-col gap-3 rounded-xl border bg-card p-3 sm:flex-row"><div className="flex flex-1 items-center gap-2 rounded-lg bg-muted/60 px-3 py-2"><Search className="size-4 text-muted-foreground" /><input className="w-full bg-transparent text-sm outline-none" placeholder="Search documents..." /></div><button className="flex items-center justify-center gap-2 rounded-lg border px-3 py-2 text-xs font-medium"><Filter className="size-3.5" />Filters</button></div><div className="mb-5 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border bg-card p-4"><div className="text-xs text-muted-foreground">Total documents</div><div className="mt-1 text-2xl font-semibold">12,482</div></div><div className="rounded-xl border bg-card p-4"><div className="text-xs text-muted-foreground">Indexed successfully</div><div className="mt-1 text-2xl font-semibold text-emerald-600">12,361</div></div><div className="rounded-xl border bg-card p-4"><div className="text-xs text-muted-foreground">Needs attention</div><div className="mt-1 text-2xl font-semibold text-amber-600">24</div></div></div><div className="overflow-hidden rounded-xl border bg-card"><div className="hidden grid-cols-[2fr_1fr_1.2fr_1fr_1fr_40px] gap-4 border-b bg-muted/30 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground lg:grid"><span>Document</span><span>Type</span><span>Collection</span><span>Uploaded</span><span>Status</span><span /></div>{documents.map((d,i)=><button key={d} onClick={()=>go(`/documents/${i+1}`)} className="grid w-full gap-2 border-b px-5 py-4 text-left transition hover:bg-muted/30 last:border-0 lg:grid-cols-[2fr_1fr_1.2fr_1fr_1fr_40px] lg:items-center lg:gap-4"><div className="flex items-center gap-3"><div className="grid size-8 place-items-center rounded-lg bg-red-500/10 text-red-600"><FileText className="size-4" /></div><div><div className="text-sm font-medium">{d}</div><div className="mt-1 text-xs text-muted-foreground">{['2.4 MB · 86 chunks','4.8 MB · 214 chunks','1.2 MB · 48 chunks'][i%3]}</div></div></div><div className="text-xs text-muted-foreground">{d.endsWith('docx')?'DOCX':'PDF'}</div><div className="text-xs text-muted-foreground">{['HR Policies','HR','Security','HR & Compliance'][i%4]}</div><div className="text-xs text-muted-foreground">{i%2?'Yesterday':'Jun 16, 2026'}</div><div><StatusBadge tone={i===7?'amber':'green'}>{i===7?'Needs review':'Indexed'}</StatusBadge></div><MoreHorizontal className="size-4 text-muted-foreground" /></button>)}</div></div> }

function DocumentDetail({ onBack }: any) { return <div><button onClick={onBack} className="mb-5 flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><ChevronLeft className="size-4" />Back to documents</button><PageIntro eyebrow="Document detail" title="Remote Work Policy.pdf" description="Referenced by 28 conversations across HR Policies." action={<button className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium"><Download className="size-4" />Download</button>} /><div className="grid gap-5 xl:grid-cols-[240px_1fr_300px]"><aside className="rounded-xl border bg-card p-4"><h3 className="text-sm font-semibold">Document information</h3><div className="mt-5 flex flex-col gap-4">{[['File type','PDF'],['File size','2.4 MB'],['Uploaded by','People Operations'],['Upload date','Jun 12, 2026'],['Collection','HR Policies'],['Chunks','86']].map(r=><div key={r[0]}><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{r[0]}</div><div className="mt-1 text-sm font-medium">{r[1]}</div></div>)}</div><div className="mt-6 border-t pt-4"><div className="mb-2 text-xs text-muted-foreground">Indexing status</div><StatusBadge>Indexed</StatusBadge></div></aside><div className="min-h-[620px] rounded-xl border bg-muted/30 p-3"><div className="mb-3 flex items-center justify-between rounded-lg border bg-card px-3 py-2"><div className="flex items-center gap-2 text-xs text-muted-foreground"><Search className="size-3.5" />Search within document</div><div className="flex items-center gap-1"><IconButton icon={ChevronLeft} label="Previous page" /><span className="px-2 text-xs">Page 8 of 12</span><IconButton icon={ChevronRight} label="Next page" /></div></div><div className="mx-auto max-w-2xl rounded-sm border bg-white p-8 text-slate-800 shadow-sm sm:p-12"><div className="mb-8 border-b pb-5"><div className="text-[10px] font-semibold uppercase tracking-[.2em] text-slate-400">People Operations · HR Policies</div><h2 className="mt-4 text-xl font-semibold">Remote Work Policy</h2><p className="mt-2 text-xs text-slate-400">Version 3.2 · Effective January 15, 2026</p></div><h3 className="text-sm font-semibold">4. International remote work</h3><p className="mt-4 text-xs leading-6 text-slate-600">Employees may work remotely outside their home country for up to <mark className="rounded bg-amber-100 px-1 text-slate-800">30 consecutive days</mark> in a calendar year, subject to manager approval and applicable local legal requirements.</p><p className="mt-4 text-xs leading-6 text-slate-600">International remote work requests must be submitted at least 10 business days in advance. Employees are responsible for ensuring they have the right to work from the requested location.</p><h3 className="mt-7 text-sm font-semibold">4.1 Approval requirements</h3><p className="mt-4 text-xs leading-6 text-slate-600">Approval is required from the employee&apos;s manager and People Operations. Additional review may be required for tax, payroll, data protection, or information security considerations.</p><div className="mt-16 text-center text-[10px] text-slate-400">Remote Work Policy · Page 8</div></div></div><aside className="rounded-xl border bg-card p-4"><h3 className="flex items-center gap-2 text-sm font-semibold"><Sparkles className="size-4 text-primary" />Referenced by Cortex</h3><p className="mt-1 text-xs text-muted-foreground">Questions that used this document</p><div className="mt-4 flex flex-col gap-2">{['Can I work remotely from Spain?','What is the international work limit?','Do I need manager approval?'].map(q=><div key={q} className="rounded-lg bg-muted/50 p-3 text-xs leading-5">{q}</div>)}</div><div className="mt-6 border-t pt-4"><h3 className="text-sm font-semibold">Relevant chunks</h3><div className="mt-3 flex flex-col gap-2">{['International remote work · 96%','Approval requirements · 92%','Tax and payroll review · 84%'].map((q,i)=><button key={q} className="w-full rounded-lg border p-3 text-left hover:border-primary/40"><div className="text-xs font-medium">{q}</div><div className="mt-1 text-[10px] text-muted-foreground">Page {8+i} · Click to highlight</div></button>)}</div></div></aside></div></div> }

function Collections({ go }: any) { return <div><PageIntro eyebrow="Knowledge organization" title="Collections" description="Organize enterprise knowledge into focused, permission-aware libraries." action={<button className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground"><Plus className="size-4" />Create collection</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{collections.map(([name,desc,docs,chunks,updated,Icon])=><div key={name} className="group rounded-xl border bg-card p-5 transition hover:-translate-y-0.5 hover:border-primary/30 hover:shadow-sm"><div className="flex items-start justify-between"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="size-5" /></div><button className="opacity-0 transition group-hover:opacity-100" aria-label="Collection actions"><MoreHorizontal className="size-4 text-muted-foreground" /></button></div><h3 className="mt-5 font-semibold">{name}</h3><p className="mt-2 min-h-10 text-xs leading-5 text-muted-foreground">{desc}</p><div className="mt-5 flex items-center gap-4 text-xs"><span className="flex items-center gap-1.5"><FileText className="size-3.5 text-muted-foreground" />{docs} documents</span><span className="flex items-center gap-1.5"><Database className="size-3.5 text-muted-foreground" />{chunks} chunks</span></div><div className="mt-4 flex items-center justify-between border-t pt-4"><span className="text-[10px] text-muted-foreground">Updated {updated}</span><button onClick={()=>go('/collections/1')} className="text-xs font-medium text-primary hover:underline">Open</button></div></div>)}</div></div> }
function CollectionDetail({ onBack }: any) { return <div><button onClick={onBack} className="mb-5 flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><ChevronLeft className="size-4" />Back to collections</button><PageIntro eyebrow="Collection" title="HR Policies" description="Company policies, employee guidelines and benefits documentation." action={<button className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium"><Settings className="size-4" />Manage access</button>} /><div className="mb-6 grid gap-3 sm:grid-cols-4">{[['Documents','324'],['Chunks','48,210'],['Last indexed','2 hours ago'],['Access level','Restricted']].map(r=><div key={r[0]} className="rounded-xl border bg-card p-4"><div className="text-xs text-muted-foreground">{r[0]}</div><div className="mt-1 font-semibold">{r[1]}</div></div>)}</div><div className="flex gap-1 border-b"><button className="border-b-2 border-primary px-4 py-3 text-xs font-medium text-primary">Documents</button><button className="px-4 py-3 text-xs text-muted-foreground">Search</button><button className="px-4 py-3 text-xs text-muted-foreground">Activity</button><button className="px-4 py-3 text-xs text-muted-foreground">Permissions</button></div><div className="mt-5 flex items-center gap-2 rounded-lg border bg-card px-3 py-2 sm:w-80"><Search className="size-4 text-muted-foreground" /><input className="w-full bg-transparent text-sm outline-none" placeholder="Search within HR Policies" /></div><div className="mt-5 rounded-xl border bg-card">{documents.slice(0,5).map(d=><div key={d} className="flex items-center gap-3 border-b p-4 last:border-0"><div className="grid size-8 place-items-center rounded-lg bg-red-500/10 text-red-600"><FileText className="size-4" /></div><div className="flex-1"><div className="text-sm font-medium">{d}</div><div className="mt-1 text-xs text-muted-foreground">Matching excerpt available · 86 chunks</div></div><span className="text-xs text-muted-foreground">Open</span><ArrowUpRight className="size-4 text-muted-foreground" /></div>)}</div></div> }

function SearchPage({ onSource }: any) { return <div><PageIntro eyebrow="Enterprise discovery" title="Global Search" description="Find trusted knowledge across documents, conversations and collections." /><div className="rounded-2xl border bg-card p-2 shadow-sm"><div className="flex items-center gap-3 px-3 py-2"><Search className="size-5 text-primary" /><input autoFocus className="flex-1 bg-transparent text-sm outline-none" placeholder="Search your organization&apos;s knowledge..." defaultValue="remote work approval" /><button className="rounded-lg bg-primary px-4 py-2 text-xs font-medium text-primary-foreground">Search</button></div></div><div className="mt-7 flex flex-col gap-6 lg:flex-row"><aside className="w-full shrink-0 rounded-xl border bg-card p-4 lg:w-56"><div className="flex items-center justify-between"><h3 className="text-sm font-semibold">Filters</h3><button className="text-xs text-primary">Clear</button></div>{[['Content type',['Documents','Conversations']],['Collection',['HR Policies','Security','Engineering']],['Relevance',['Highly relevant','All results']]].map(([h,opts])=><div key={h as string} className="mt-6"><div className="text-xs font-medium">{h as string}</div><div className="mt-3 flex flex-col gap-2">{(opts as string[]).map(o=><label key={o} className="flex items-center gap-2 text-xs text-muted-foreground"><input type="checkbox" defaultChecked={o==='Documents'||o==='Highly relevant'} className="accent-primary" />{o}</label>)}</div></div>)}</aside><div className="min-w-0 flex-1"><div className="mb-3 flex items-center justify-between text-xs text-muted-foreground"><span>24 results for <strong className="text-foreground">remote work approval</strong></span><button className="flex items-center gap-1"><ListFilter className="size-3.5" />Most relevant</button></div><div className="flex flex-col gap-3">{sources.concat([['Expense Reimbursement Policy.pdf','Page 12','HR Policies',82]]).map((s,i)=><button onClick={onSource} key={s[0]} className="rounded-xl border bg-card p-5 text-left transition hover:border-primary/40"><div className="flex items-start gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-red-500/10 text-red-600"><FileText className="size-4" /></div><div className="min-w-0 flex-1"><div className="font-medium">{s[0]}</div><div className="mt-1 text-xs text-muted-foreground">{s[1]} · {s[2]}</div><p className="mt-3 text-sm leading-6 text-muted-foreground">Employees requesting <mark className="rounded bg-amber-100 px-1 text-foreground">remote work approval</mark> outside their home country must submit a request in advance...</p><div className="mt-3 flex items-center gap-3 text-xs"><span className="text-primary">Document</span><Confidence value={s[3] as number} /></div></div><ArrowUpRight className="size-4 text-muted-foreground" /></div></button>)}</div></div></div></div> }

function AnalyticsPage() { return <div><PageIntro eyebrow="Workspace intelligence" title="Analytics" description="Monitor knowledge usage, retrieval quality and answer performance." action={<button className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium"><Download className="size-4" />Export report</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><MetricCard icon={MessageCircle} label="Total questions" value="48,291" trend="+14.6%" /><MetricCard icon={Activity} label="Questions this week" value="4,218" trend="+8.2%" /><MetricCard icon={Gauge} label="Average confidence" value="92.4%" trend="+1.8%" color="green" /><MetricCard icon={Clock3} label="Avg response time" value="2.4s" trend="-0.3s" color="green" /><MetricCard icon={TargetIcon} label="Retrieval accuracy" value="94.8%" trend="+2.1%" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_1fr]"><div className="rounded-xl border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Questions over time</h2><p className="mt-1 text-xs text-muted-foreground">Daily questions across all collections</p></div><button className="rounded-lg border px-2.5 py-1.5 text-xs">Last 7 days <ChevronDown className="ml-1 inline size-3" /></button></div><div className="mt-6 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activityData}><defs><linearGradient id="qfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4f46e5" stopOpacity={.22}/><stop offset="100%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)" /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:11}} /><YAxis hide /><Tooltip /><Area type="monotone" dataKey="questions" stroke="#4f46e5" fill="url(#qfill)" strokeWidth={2} /></AreaChart></ResponsiveContainer></div></div><div className="rounded-xl border bg-card p-5"><h2 className="font-semibold">Confidence distribution</h2><p className="mt-1 text-xs text-muted-foreground">Answer quality by confidence band</p><div className="h-64"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={confidenceData} dataKey="value" nameKey="name" cx="50%" cy="45%" innerRadius={62} outerRadius={88} paddingAngle={3}>{confidenceData.map((e,i)=><Cell key={e.name} fill={['#16a34a','#f59e0b','#dc2626'][i]} />)}</Pie><Tooltip /><Legend iconType="circle" wrapperStyle={{fontSize:12}} /></PieChart></ResponsiveContainer></div></div></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><div className="rounded-xl border bg-card p-5"><h2 className="font-semibold">Questions by category</h2><div className="mt-5 h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={categoryData} layout="vertical"><CartesianGrid horizontal={false} stroke="var(--border)" /><XAxis type="number" hide /><YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:11}} width={90} /><Tooltip /><Bar dataKey="value" fill="#4f46e5" radius={[0,4,4,0]} barSize={22} /></BarChart></ResponsiveContainer></div></div><div className="rounded-xl border bg-card p-5"><h2 className="font-semibold">Most referenced documents</h2><div className="mt-5 flex flex-col gap-4">{[['Remote Work Policy.pdf','1,284 citations','96%'],['Information Security Policy.pdf','982 citations','94%'],['Employee Handbook.pdf','846 citations','92%'],['Incident Response Playbook.pdf','621 citations','89%']].map((r,i)=><div key={r[0]} className="flex items-center gap-3"><div className="grid size-7 place-items-center rounded-lg bg-muted text-xs font-semibold text-muted-foreground">{i+1}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium">{r[0]}</div><div className="mt-1 text-xs text-muted-foreground">{r[1]}</div></div><span className="text-xs font-medium text-emerald-600">{r[2]}</span></div>)}</div></div></div></div> }
function TargetIcon(props:any){return <Gauge {...props} />}

function UsersPage({ onToast }: any) { const rows=[['Alex Morgan','alex.morgan@acme.com','Administrator','All collections','1,482','Active'],['Priya Shah','priya.shah@acme.com','Knowledge Manager','HR, Legal','928','Active'],['Marcus Chen','marcus.chen@acme.com','Employee','Engineering','384','Active'],['Elena Rossi','elena.rossi@acme.com','Viewer','Finance','92','Invited'],['James Wilson','james.wilson@acme.com','Employee','Customer Support','218','Active']]; return <div><PageIntro eyebrow="Workspace administration" title="Users & Roles" description="Manage access, permissions and knowledge workspace membership." action={<button onClick={()=>onToast('Invite user dialog opened')} className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground"><UserPlus className="size-4" />Invite user</button>} /><div className="mb-5 flex items-center justify-between rounded-xl border bg-card p-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-primary/10 text-primary"><Users className="size-4" /></div><div><div className="text-sm font-medium">18 active members</div><div className="text-xs text-muted-foreground">2 pending invitations</div></div></div><button className="text-xs font-medium text-primary">Manage roles</button></div><div className="overflow-hidden rounded-xl border bg-card"><div className="hidden grid-cols-[1.5fr_1.8fr_1.2fr_1.3fr_.8fr_1fr_40px] gap-4 border-b bg-muted/30 px-5 py-3 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground xl:grid"><span>User</span><span>Email</span><span>Role</span><span>Collections</span><span>Questions</span><span>Status</span><span /></div>{rows.map(r=><div key={r[1]} className="grid gap-3 border-b px-5 py-4 last:border-0 xl:grid-cols-[1.5fr_1.8fr_1.2fr_1.3fr_.8fr_1fr_40px] xl:items-center xl:gap-4"><div className="flex items-center gap-3"><div className="grid size-8 place-items-center rounded-full bg-indigo-100 text-xs font-semibold text-indigo-700">{r[0].split(' ').map(x=>x[0]).join('')}</div><span className="text-sm font-medium">{r[0]}</span></div><div className="text-xs text-muted-foreground">{r[1]}</div><span className="w-fit rounded-md bg-muted px-2 py-1 text-xs font-medium">{r[2]}</span><div className="text-xs text-muted-foreground">{r[3]}</div><div className="text-xs text-muted-foreground">{r[4]}</div><div><StatusBadge tone={r[5]==='Invited'?'amber':'green'}>{r[5]}</StatusBadge></div><button aria-label="User actions"><MoreHorizontal className="size-4 text-muted-foreground" /></button></div>)}</div></div> }
function SettingsPage({ onToast }: any) { const [tab,setTab]=useState('General'); const tabs=['General','AI Configuration','Retrieval','Security','Notifications','Integrations']; return <div><PageIntro eyebrow="Workspace controls" title="Settings" description="Configure how CortexSearch retrieves, answers and protects knowledge." /><div className="grid gap-6 lg:grid-cols-[200px_1fr]"><aside className="flex gap-1 overflow-auto lg:flex-col">{tabs.map(t=><button key={t} onClick={()=>setTab(t)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-left text-sm ${tab===t?'bg-primary/10 font-medium text-primary':'text-muted-foreground hover:bg-accent'}`}>{t}</button>)}</aside><section className="rounded-xl border bg-card p-5 sm:p-7"><div className="border-b pb-5"><h2 className="font-semibold">{tab}</h2><p className="mt-1 text-sm text-muted-foreground">{tab==='AI Configuration'?'Tune answer generation for your organization.':tab==='Retrieval'?'Control how documents are searched and ranked.':'Manage your CortexSearch workspace preferences.'}</p></div>{tab==='Security'?<div className="mt-6 flex flex-col gap-5">{['RBAC enabled','SSO connection','Audit logging','Document permissions'].map((x,i)=><div key={x} className="flex items-center justify-between border-b pb-4"><div><div className="text-sm font-medium">{x}</div><div className="mt-1 text-xs text-muted-foreground">Enterprise security control</div></div><button onClick={()=>onToast(`${x} updated`)} className={`relative h-6 w-11 rounded-full ${i===1?'bg-muted':'bg-primary'}`}><span className={`absolute top-1 size-4 rounded-full bg-white transition ${i===1?'left-1':'right-1'}`} /></button></div>)}</div>:<div className="mt-6 grid gap-5 sm:grid-cols-2">{[['Model','Cortex LLM'],['Temperature','0.2'],['Maximum context','8,000 tokens'],['Response style','Grounded and concise'],['Vector search weight','70%'],['Keyword search weight','30%'],['Top K','8'],['Confidence threshold','0.72']].map(([l,v])=><label key={l} className="flex flex-col gap-2"><span className="text-xs font-medium">{l}</span><div className="flex items-center rounded-lg border bg-background px-3 py-2 text-sm"><input defaultValue={v} className="w-full bg-transparent outline-none" /><ChevronDown className="size-3.5 text-muted-foreground" /></div></label>)}</div>}<div className="mt-8 flex justify-end"><button onClick={()=>onToast('Settings saved')} className="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Save changes</button></div></section></div></div> }
function CommandPalette({ close, go }: any) { const items=[['Ask Cortex','/dashboard',Sparkles],['Search documents','/search',Search],['New conversation','/chat',Plus],['Upload document','/documents',Upload],['Open collections','/collections',Library],['Open analytics','/analytics',BarChart3],['Open settings','/settings',Settings]]; return <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/30 px-4 pt-[15vh]" onClick={close}><div className="w-full max-w-lg overflow-hidden rounded-xl border bg-card shadow-2xl" onClick={e=>e.stopPropagation()}><div className="flex items-center gap-3 border-b px-4"><Search className="size-4 text-muted-foreground" /><input autoFocus placeholder="Search commands..." className="h-12 flex-1 bg-transparent text-sm outline-none" /><kbd className="rounded bg-muted px-1.5 py-0.5 text-[10px]">ESC</kbd></div><div className="p-2">{items.map(([label,path,Icon])=><button key={label as string} onClick={()=>go(path)} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm hover:bg-accent"><Icon className="size-4 text-muted-foreground" />{label as string}<ArrowUpRight className="ml-auto size-3.5 text-muted-foreground" /></button>)}</div><div className="flex items-center gap-2 border-t bg-muted/30 px-4 py-2 text-[10px] text-muted-foreground"><Command className="size-3" />Navigate with keyboard <span className="ml-auto">CortexSearch</span></div></div></div> }
function SourceModal({ close }: any) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4" onClick={close}><div className="flex max-h-[90vh] w-full max-w-4xl flex-col overflow-hidden rounded-xl border bg-card shadow-2xl" onClick={e=>e.stopPropagation()}><div className="flex items-center justify-between border-b px-5 py-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-red-500/10 text-red-600"><FileText className="size-4" /></div><div><h2 className="text-sm font-semibold">Remote Work Policy.pdf</h2><p className="mt-1 text-xs text-muted-foreground">Page 8 · HR Policies · 96% relevance</p></div></div><IconButton icon={X} label="Close source preview" onClick={close} /></div><div className="grid min-h-0 flex-1 bg-muted/30 md:grid-cols-[1fr_260px]"><div className="overflow-auto p-5 sm:p-8"><div className="mx-auto max-w-xl bg-white p-8 text-slate-800 shadow-sm sm:p-12"><div className="text-[10px] font-semibold uppercase tracking-[.2em] text-slate-400">People Operations</div><h3 className="mt-5 text-xl font-semibold">Remote Work Policy</h3><div className="mt-8 border-l-2 border-primary bg-primary/5 p-4"><p className="text-xs leading-6">Employees may work remotely outside their home country for up to <mark className="rounded bg-amber-100 px-1">30 consecutive days</mark> in a calendar year, subject to manager approval and applicable local legal requirements.</p></div><p className="mt-5 text-xs leading-6 text-slate-600">International remote work requests must be submitted at least 10 business days in advance. Employees are responsible for ensuring they have the right to work from the requested location.</p><div className="mt-16 text-center text-[10px] text-slate-400">Page 8</div></div></div><aside className="border-l bg-card p-5"><h3 className="text-sm font-semibold">Source details</h3><div className="mt-5 flex flex-col gap-4">{[['Collection','HR Policies'],['Relevance','96%'],['Document type','PDF'],['Last updated','Jun 12, 2026']].map(r=><div key={r[0]}><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{r[0]}</div><div className="mt-1 text-sm font-medium">{r[1]}</div></div>)}</div><button className="mt-8 flex w-full items-center justify-center gap-2 rounded-lg border px-3 py-2 text-xs font-medium"><ArrowUpRight className="size-3.5" />Open full document</button></aside></div></div></div> }

// Intentional compact placeholder to keep the route shell readable while retaining accessible states.
function Placeholder(){return null}
